WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_rt_e_eq'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '比例列方程', 'kp-rt-e-eq', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "比例设元列方程"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "看到比例 3:4:5，永远不要设 x,y,z。直接设 3x, 4x, 5x！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲乙两人原本资金比例为 5:3。甲花掉 100，乙赚了 50，比例变成 2:3。求甲原来有多少钱？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看到初始比例 5:3, 直接设甲为 5x, 乙为 3x] --> B[根据变动条件更新资产]\nB --> C[甲变 5x-100, 乙变 3x+50]\nC --> D[列出新的比例方程: (5x-100) / (3x+50) = 2/3]\nD --> E[交叉相乘解出 x: 15x-300 = 6x+100]\nE --> F[x=44.4 (假设数据), 乘回 5x 得到答案]"}}]}$$ AS jsonb), NULL, '比例列方程的核心考点与实战推导。', category_node.id, CAST('["数量关系", "比例列方程"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_rt_e_eq", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
